from itertools import permutations

# Define the size of the grid
n = 12

# Fixed values
fixed_values = {3: 8, 8: 2}

# Function to check if a permutation is a Costas array
def is_costas_array(p):
    # Check if all displacement vectors are pairwise distinct
    displacement_vectors = set()
    for i in range(n):
        for j in range(i + 1, n):
            dr = p[j] - p[i]
            dc = j - i
            if (dr, dc) in displacement_vectors:
                return False
            displacement_vectors.add((dr, dc))
    return True

# Generate all permutations and check if they are Costas arrays
for p in permutations(range(n)):
    # Check if the permutation respects the fixed values
    if all(p[i] == fixed_values[i] for i in fixed_values):
        # Check if the permutation is a Costas array
        if is_costas_array(p):
            print(p)
            break
else:
    print("UNSATISFIABLE")
